import { describe, expect, it } from "vitest";
import { formatG, pyRound, pyStr } from "../../src/lib/format.ts";
import table from "./python-format.json";

// Generated by CPython 3 from 343 values (ties, binary near-ties, tiny, huge, random); see the commit that added it.
describe("Python number formatting matches CPython", () => {
  it("pyRound(x, n) equals round(x, n) for n in 0..3 and -1", () => {
    for (const row of table) {
      expect([row.x, pyRound(row.x)]).toEqual([row.x, row.r0]);
      expect([row.x, pyRound(row.x, 1)]).toEqual([row.x, row.r1]);
      expect([row.x, pyRound(row.x, 2)]).toEqual([row.x, row.r2]);
      expect([row.x, pyRound(row.x, 3)]).toEqual([row.x, row.r3]);
      expect([row.x, pyRound(row.x, -1)]).toEqual([row.x, row.rm1]);
    }
  });

  it('formatG(x) equals "%g" % x and "%.3g" % x', () => {
    for (const row of table) {
      expect([row.x, formatG(row.x)]).toEqual([row.x, row.g]);
      expect([row.x, formatG(row.x, 3)]).toEqual([row.x, row.g3]);
    }
  });

  it("pyStr(x) equals repr(x)", () => {
    for (const row of table) expect([row.x, pyStr(row.x)]).toEqual([row.x, row.repr]);
  });

  it("ties round half to even, on the exact binary value", () => {
    expect(pyRound(0.5)).toBe(0);
    expect(pyRound(1.5)).toBe(2);
    expect(pyRound(2.5)).toBe(2);
    expect(pyRound(2.675, 2)).toBe(2.67); // 2.67499999... in binary
    expect(pyRound(0.125, 2)).toBe(0.12); // exact tie
    expect(formatG(0.5, 0)).toBe("0.5");
    expect(formatG(Number.NaN)).toBe("nan");
    expect(formatG(-Infinity)).toBe("-inf");
    expect(formatG(0)).toBe("0");
  });
});
